import json, os, glob

# 列出所有 jsonl
files = sorted(glob.glob("*.jsonl"))
exclude = "caaed8f5-91fa-46aa-a8d5-29b6517b52cc.jsonl"  # 本場
print(f"Total files: {len(files)}")

# 搜尋關鍵字
keywords = {
    "#03": ["你都沒看","你自己看","你檢查了","看過嗎","親自看"],
    "#05": ["commit hash","沒推上去","hash 呢","凡走過必留","沒做完不要說"],
    "#15": ["你確定嗎","你是不是亂","不知道就說","你查了嗎","你瞎掰","別瞎說"],
    "#19": ["心跳沒意義","心跳要有","你的心跳","為什麼還沒心跳"],
    "#21": ["一字不差","原文引用","你引用錯","不是這樣寫","守則內容"],
}

results = {k:[] for k in keywords}

for fname in files:
    if fname == exclude: continue
    try:
        with open(fname) as f:
            for line in f:
                try:
                    d = json.loads(line)
                    if d.get('type') != 'user': continue
                    msg = d.get('message', {})
                    content = msg.get('content', '')
                    if isinstance(content, str):
                        txt = content
                    elif isinstance(content, list):
                        parts = []
                        for c in content:
                            if isinstance(c, dict) and 'text' in c:
                                parts.append(c['text'])
                        txt = '\n'.join(parts)
                    else:
                        continue
                    # 排除 hook/sys
                    if '<system-reminder>' in txt: continue
                    if 'UserPromptSubmit hook' in txt: continue
                    if 'persisted-output' in txt: continue
                    if 'tool_use_id' in txt: continue
                    # 也排除過長（多半是 hook 注入）
                    if len(txt) > 2000: continue

                    for rule, kws in keywords.items():
                        for kw in kws:
                            if kw in txt:
                                ts = d.get('timestamp','?')[:19]
                                results[rule].append((ts, fname[:8], kw, txt[:400]))
                                break
                except Exception:
                    pass
    except Exception:
        pass

for rule in keywords:
    print(f"\n========= {rule} ({len(results[rule])} hits) =========")
    for ts, f, kw, t in results[rule][:5]:
        print(f"[{ts}] {f} | KW:{kw}")
        print(t)
        print("---")
